15	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	};
21	
22	const basePremiumOf = (item: Item): number =>
23	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
24	
25	export const quote = (customer: Customer, items: Item[]): number => {
26	  const basePremium = items
27	    .map(basePremiumOf)
28	    .reduce((sum, premium) => sum + premium, 0);
29	  return basePremium + PROCESSING_FEE;
30	};
